// This file is generated by AI.

// 开始界面: 顶部固定一行 (品牌 + 搜索 + 新建/打开), 下面是可滚动的最近项目。
//
// 两条布局约定:
// * **只有项目列表滚动**: 品牌与操作一直留在原地, 列表长了也不会把按钮顶出视野;
// * 搜索框与两个按钮**同层同行**: 三者都是"对列表做的事", 分两层会让眼睛来回找。
//
// 项目名与简介来自各自项目 `game/config.txt` 里的 `Game_name` / `Description` (由后端
// 用语言服务同一套解析器读出)。列表先按持久化的缓存画出来, 再异步刷新一遍 ——
// 既不白屏, 也能看到别的工具刚改过的名字。

import { open } from '@tauri-apps/plugin-dialog';
import { revealItemInDir } from '@tauri-apps/plugin-opener';
import { Button, Input } from '@fluentui/react-components';
import {
  AddRegular,
  DeleteRegular,
  DismissRegular,
  FolderOpenRegular,
  OpenFolderRegular,
  SearchRegular,
} from '@fluentui/react-icons';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { moveToTrash } from '../commands/server';
import { requestAlert, requestConfirm } from '../confirm';
import { fs } from '../lib/fs';
import {
  filterRecentProjects,
  projectDisplayName,
  removeRecentProject,
  sortRecentProjects,
} from '../lib/recentProjects';
import { openProject, readProjectConfigSummary } from '../project';
import { useAppStore } from '../state/store';
import { ContextMenu } from './ContextMenu';
import { NewProjectDialog } from './NewProjectDialog';
import { RecentProjectCard, type RecentProjectView } from './RecentProjectCard';

/** 刷新后得到的项目状态 (仅存活于本次会话) */
interface ProjectState {
  available: boolean;
  name?: string;
  description?: string;
  titleImg?: string;
}

export function WelcomePage() {
  const settings = useAppStore((s) => s.settings);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const setSettingsCategory = useAppStore((s) => s.setSettingsCategory);

  const [query, setQuery] = useState('');
  const [creating, setCreating] = useState(false);
  const [states, setStates] = useState<Record<string, ProjectState>>({});
  const [menu, setMenu] = useState<{ path: string; x: number; y: number } | null>(null);

  /*
   * 只在挂载时记下要刷新的项目: 刷新过程本身会写回 settings, 若把 settings 作为依赖,
   * 就会"刷新 -> 设置变化 -> 再刷新"地循环。
   */
  const initialPaths = useRef(useAppStore.getState().settings.recentProjects.map((item) => item.path));

  const refreshStates = useCallback(async (paths: string[]) => {
    if (paths.length === 0) return;
    const results = await Promise.all(
      paths.map(async (path) => {
        const [summary, stat] = await Promise.all([readProjectConfigSummary(path), fs.exists(path)]);
        return { path, summary, available: stat.exists };
      })
    );

    const next: Record<string, ProjectState> = {};
    for (const result of results) {
      next[result.path.toLowerCase()] = {
        available: result.available,
        name: result.summary.name || undefined,
        description: result.summary.description || undefined,
        titleImg: result.summary.titleImg || undefined,
      };
    }
    setStates(next);

    // 顺手把最新值写回设置: 下次启动先按缓存显示, 再异步刷新
    const store = useAppStore.getState();
    store.updateSettings({
      recentProjects: store.settings.recentProjects.map((item) => {
        const state = next[item.path.toLowerCase()];
        if (!state) return item;
        return {
          ...item,
          name: state.name ?? item.name,
          description: state.description ?? item.description,
          titleImg: state.titleImg ?? item.titleImg,
        };
      }),
    });
  }, []);

  useEffect(() => {
    void refreshStates(initialPaths.current);
  }, [refreshStates]);

  const recents = useMemo(() => sortRecentProjects(settings.recentProjects), [settings.recentProjects]);

  const views = useMemo<RecentProjectView[]>(
    () =>
      recents.map((item) => {
        const state = states[item.path.toLowerCase()];
        return {
          path: item.path,
          name: state?.name ?? projectDisplayName(item),
          titleImg: state?.titleImg ?? item.titleImg,
          lastOpened: item.lastOpened,
          available: state?.available ?? true,
        };
      }),
    [recents, states]
  );

  const visible = useMemo(() => filterRecentProjects(views, query), [views, query]);

  /**
   * 打开项目。
   *
   * 过程里**不动页面**: 不显示"正在打开"、不在页面上写错误 —— 打开是用户自己的动作,
   * 成功就是页面切到编辑器, 失败就弹一个框说清楚。
   */
  const openPath = async (path: string) => {
    try {
      await openProject(path);
    } catch (e) {
      requestAlert('无法打开项目', `${path}\n\n${String(e)}`);
    }
  };

  const pickAndOpen = async () => {
    const dir = await open({ directory: true, title: '选择 WebGAL 项目目录' });
    if (typeof dir === 'string') await openPath(dir);
  };

  const removeFromList = (path: string) => {
    const store = useAppStore.getState();
    store.updateSettings({ recentProjects: removeRecentProject(store.settings.recentProjects, path) });
  };

  /** 移入回收站是不可逆到"要点两次"的操作: 仍走确认框 (与"从列表移除"分开)。 */
  const trashProject = (path: string, name: string) => {
    requestConfirm({
      title: '移入回收站',
      description: `将「${name}」的整个项目文件夹移入系统回收站（可恢复）。`,
      confirmLabel: '移入回收站',
      danger: true,
      action: () => {
        void (async () => {
          try {
            await moveToTrash(path);
            removeFromList(path);
          } catch (e) {
            requestAlert('删除失败', String(e));
          }
        })();
      },
    });
  };

  const menuProject = menu ? views.find((item) => item.path === menu.path) : undefined;

  return (
    <div className="welcome">
      <header className="welcome-head">
        <div className="welcome-brand">
          <img className="welcome-mark" src="/ink-icon.svg" alt="" draggable={false} />
          <div className="welcome-brand-text">
            <h1 className="welcome-title">WebGAL Ink</h1>
            <p className="welcome-subtitle">WebGAL 视觉小说代码编辑器</p>
          </div>
        </div>

        <div className="welcome-toolbar">
          <Input
            className="welcome-search"
            contentBefore={<SearchRegular />}
            placeholder="搜索项目"
            value={query}
            onChange={(_, data) => setQuery(data.value)}
          />
          <Button appearance="primary" icon={<AddRegular />} onClick={() => setCreating(true)}>
            新建项目
          </Button>
          <Button icon={<FolderOpenRegular />} onClick={() => void pickAndOpen()}>
            打开项目
          </Button>
        </div>
      </header>

      <div className="welcome-body">
        <div className="welcome-section-head">
          <h3>最近项目</h3>
          {views.length > 0 ? (
            <span className="muted">{query.trim() ? `${visible.length} / ${views.length}` : `${views.length} 个`}</span>
          ) : null}
        </div>

        {views.length === 0 ? (
          <p className="welcome-empty">
            还没有项目。用「新建项目」由引擎生成一个，或「打开项目」打开已有的 WebGAL 项目目录。
          </p>
        ) : visible.length === 0 ? (
          <p className="welcome-empty">没有匹配「{query.trim()}」的项目</p>
        ) : (
          <div className="project-grid">
            {visible.map((project) => (
              <RecentProjectCard
                key={project.path}
                project={project}
                onOpen={() => void openPath(project.path)}
                onMenu={(position) => setMenu({ path: project.path, x: position.x, y: position.y })}
                onContextMenu={(event) => {
                  event.preventDefault();
                  setMenu({ path: project.path, x: event.clientX, y: event.clientY });
                }}
              />
            ))}
          </div>
        )}
      </div>

      {menu && menuProject ? (
        <ContextMenu
          x={menu.x}
          y={menu.y}
          onClose={() => setMenu(null)}
          items={[
            {
              key: 'open',
              label: '打开项目',
              icon: <FolderOpenRegular />,
              onClick: () => void openPath(menuProject.path),
            },
            {
              key: 'reveal',
              label: '在文件管理器中打开',
              icon: <OpenFolderRegular />,
              onClick: () => void revealItemInDir(menuProject.path),
            },
            {
              key: 'remove',
              label: '从列表移除',
              icon: <DismissRegular />,
              onClick: () => removeFromList(menuProject.path),
            },
            {
              key: 'trash',
              label: '移入回收站',
              icon: <DeleteRegular />,
              danger: true,
              onClick: () => trashProject(menuProject.path, menuProject.name),
            },
          ]}
        />
      ) : null}

      {creating ? (
        <NewProjectDialog
          onClose={() => setCreating(false)}
          onOpenEngineSettings={() => {
            setCreating(false);
            setSettingsCategory('engine');
            setSettingsOpen(true);
          }}
        />
      ) : null}
    </div>
  );
}
